# symmetries normalized coords on 4x4
def tr(p,k):
 r,c=p
 for _ in range(k): r,c=c,3-r # rotate cw
 return r,c
for k in range(4):
 for flip in (False,True):
  def f(p):
   r,c=p
   if flip:c=3-c
   return tr((r,c),k)
  mapped={f(p):v for p,v in src.items()}
  if set(mapped)==set(key): print(k,flip,[(p,mapped[p],key[p]) for p in key])
